import ApplicationServices
import Carbon.HIToolbox
import CoreGraphics
import Foundation

/// Ensures keyboard, pointer and tablet events carry modifiers held by ControllerKeys.
///
/// A synthesized modifier `flagsChanged` event updates the global modifier state,
/// but some device drivers create input events with their own explicit flags.
/// Apps can then miss a controller-held Shift during Wacom strokes, or Command
/// while typing on a Bluetooth chatpad. Keyboard events generated by this process
/// and modifier-key transitions are left alone to preserve their explicit flags.
/// This session event tap adds only ControllerKeys' held modifiers to those events.
nonisolated final class HeldModifierPointerEventBridge: @unchecked Sendable {
	private enum StartState {
		case idle
		case starting
		case running
		case failed
		case stopped
	}

	private let heldModifiers: @Sendable () -> CGEventFlags
	private let isSecureInputEnabled: @Sendable () -> Bool
	private let makeTap: @Sendable (CGEventMask, UnsafeMutableRawPointer) -> (any HeldModifierEventTap)?
	private let lock = NSLock()
	private var state: StartState = .idle
	private var eventTap: (any HeldModifierEventTap)?
	private var runLoop: CFRunLoop?

	init(
		heldModifiers: @escaping @Sendable () -> CGEventFlags,
		isSecureInputEnabled: @escaping @Sendable () -> Bool = { IsSecureEventInputEnabled() },
		makeTap: @escaping @Sendable (CGEventMask, UnsafeMutableRawPointer) -> (any HeldModifierEventTap)? = {
			QuartzHeldModifierEventTap(mask: $0, context: $1)
		}
	) {
		self.heldModifiers = heldModifiers
		self.isSecureInputEnabled = isSecureInputEnabled
		self.makeTap = makeTap
	}

	func startIfNeeded() {
		lock.lock()
		guard state == .idle || state == .failed else {
			lock.unlock()
			return
		}
		state = .starting
		lock.unlock()

		let ready = DispatchSemaphore(value: 0)
		let thread = Thread { [self] in
			runEventTap(ready: ready)
		}
		thread.name = "ControllerKeys held-modifier input bridge"
		thread.qualityOfService = .userInteractive
		thread.start()

		_ = ready.wait(timeout: .now() + 0.25)
	}

	func stop() {
		let runLoopToStop: CFRunLoop?
		let tapToStop: (any HeldModifierEventTap)?

		lock.lock()
		state = .stopped
		runLoopToStop = runLoop
		tapToStop = eventTap
		lock.unlock()

		tapToStop?.setEnabled(false)
		if let runLoopToStop {
			// CFRunLoopStop before CFRunLoopRun does not stop that future run.
			// Queue the stop on the owner so startup/shutdown cannot lose it.
			CFRunLoopPerformBlock(runLoopToStop, CFRunLoopMode.commonModes.rawValue) {
				CFRunLoopStop(CFRunLoopGetCurrent())
			}
			CFRunLoopWakeUp(runLoopToStop)
		}
	}

	private func runEventTap(ready: DispatchSemaphore) {
		let eventMask = HeldModifierPointerEventPolicy.eventTypes.reduce(CGEventMask(0)) {
			$0 | CGEventMask(1) << CGEventMask($1.rawValue)
		}
		let context = Unmanaged.passUnretained(self).toOpaque()

		guard let tap = makeTap(eventMask, context) else {
			lock.lock()
			if state != .stopped {
				state = .failed
			}
			lock.unlock()
			ready.signal()
			NSLog("[InputSimulator] Could not create held-modifier input event tap")
			return
		}

		// Cover both normal shutdown and a stop requested during tap creation.
		defer { tap.invalidate() }

		let currentRunLoop = CFRunLoopGetCurrent()
		let source = tap.runLoopSource

		lock.lock()
		guard state != .stopped else {
			lock.unlock()
			ready.signal()
			tap.setEnabled(false)
			return
		}
		eventTap = tap
		runLoop = currentRunLoop
		state = .running
		lock.unlock()

		CFRunLoopAddSource(currentRunLoop, source, .commonModes)
		tap.setEnabled(true)
		ready.signal()
		CFRunLoopRun()

		tap.setEnabled(false)
		CFRunLoopRemoveSource(currentRunLoop, source, .commonModes)

		lock.lock()
		eventTap = nil
		runLoop = nil
		if state != .stopped {
			state = .idle
		}
		lock.unlock()
	}

	func process(type: CGEventType, event: CGEvent) {
		guard HeldModifierPointerEventPolicy.shouldAugment(type) else { return }
		let controllerModifiers = heldModifiers()
		guard !controllerModifiers.isEmpty else { return }
		if type == .keyDown || type == .keyUp {
			guard HeldModifierPointerEventPolicy.shouldAugmentKeyboard(
				keyCode: event.getIntegerValueField(.keyboardEventKeycode),
				sourceProcessID: event.getIntegerValueField(.eventSourceUnixProcessID),
				ownProcessID: Int64(ProcessInfo.processInfo.processIdentifier),
				isSecureInputEnabled: isSecureInputEnabled()
			) else { return }
		}
		lock.withLock {
			guard state != .stopped else { return }
			event.flags = HeldModifierPointerEventPolicy.augmentedFlags(
				eventFlags: event.flags,
				heldModifiers: controllerModifiers
			)
		}
	}

	func reenableAfterDisable() {
		lock.lock()
		defer { lock.unlock() }
		guard state == .running else { return }
		eventTap?.setEnabled(true)
	}
}

nonisolated enum HeldModifierPointerEventPolicy {
	static let eventTypes: [CGEventType] = [
		.keyDown,
		.keyUp,
		.leftMouseDown,
		.leftMouseUp,
		.rightMouseDown,
		.rightMouseUp,
		.mouseMoved,
		.leftMouseDragged,
		.rightMouseDragged,
		.scrollWheel,
		.tabletPointer,
		.otherMouseDown,
		.otherMouseUp,
		.otherMouseDragged
	]

	static func shouldAugment(_ type: CGEventType) -> Bool {
		eventTypes.contains(type)
	}

	private static let modifierKeyCodes: Set<Int64> = [
		Int64(kVK_Command), Int64(kVK_RightCommand),
		Int64(kVK_Shift), Int64(kVK_RightShift),
		Int64(kVK_Option), Int64(kVK_RightOption),
		Int64(kVK_Control), Int64(kVK_RightControl),
		Int64(kVK_CapsLock), Int64(kVK_Function)
	]

	static func shouldAugmentKeyboard(
		keyCode: Int64,
		sourceProcessID: Int64,
		ownProcessID: Int64,
		isSecureInputEnabled: Bool
	) -> Bool {
		!isSecureInputEnabled
			&& sourceProcessID != ownProcessID
			&& !modifierKeyCodes.contains(keyCode)
	}

	static func augmentedFlags(
		eventFlags: CGEventFlags,
		heldModifiers: CGEventFlags
	) -> CGEventFlags {
		eventFlags.union(heldModifiers)
	}
}

nonisolated func heldModifierPointerEventTapCallback(
	proxy: CGEventTapProxy,
	type: CGEventType,
	event: CGEvent,
	userInfo: UnsafeMutableRawPointer?
) -> Unmanaged<CGEvent>? {
	guard let userInfo else {
		return Unmanaged.passUnretained(event)
	}

	let bridge = Unmanaged<HeldModifierPointerEventBridge>
		.fromOpaque(userInfo)
		.takeUnretainedValue()

	if type == .tapDisabledByTimeout || type == .tapDisabledByUserInput {
		bridge.reenableAfterDisable()
		return Unmanaged.passUnretained(event)
	}

	bridge.process(type: type, event: event)
	return Unmanaged.passUnretained(event)
}
